list_order_custom_fields.code:
use WebCommander\Sdk\Resources\OrderCustomFields\OrderCustomFields;

$response = OrderCustomFields::listOrderCustomFields($client, ['sort' => 'label', 'dir' => 'asc']);

foreach ($response->map['order_custom_fields'] as $field) {
    echo $field['id'], ' ', $field['label'], ' (', $field['field_type'], ')', PHP_EOL;
}
echo $response->map['pagination']['total'], ' fields in total', PHP_EOL;

get_order_custom_field.code:
use WebCommander\Sdk\Resources\OrderCustomFields\OrderCustomFields;

$response = OrderCustomFields::getOrderCustomField($client, 42);

$field = $response->map['order_custom_field'];
echo $field['label'], ' (', $field['field_type'], ')', $field['is_required'] ? ' required' : '', PHP_EOL;
echo $field['hover_text'], PHP_EOL;
echo $field['placeholder'], PHP_EOL;
